CREATE TABLE IF NOT EXISTS admin_settings (key TEXT PRIMARY KEY, value TEXT, updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS site_visits (id SERIAL PRIMARY KEY, path TEXT, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS posts (id SERIAL PRIMARY KEY, title TEXT NOT NULL, content TEXT, image_url TEXT, category TEXT, published INTEGER DEFAULT 1, sort_order INTEGER DEFAULT 0, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS services (id SERIAL PRIMARY KEY, name TEXT NOT NULL, name_en TEXT, description TEXT, description_en TEXT, duration_min INTEGER DEFAULT 30, price INTEGER, sort_order INTEGER DEFAULT 0, featured INTEGER DEFAULT 0, image_url TEXT, published INTEGER DEFAULT 1, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS symptoms (id SERIAL PRIMARY KEY, name TEXT NOT NULL, name_en TEXT, category TEXT DEFAULT 'moteur', sort_order INTEGER DEFAULT 0, image_url TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS faqs (id SERIAL PRIMARY KEY, question TEXT NOT NULL, question_en TEXT, answer TEXT, answer_en TEXT, sort_order INTEGER DEFAULT 0, image_url TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS vehicles (id SERIAL PRIMARY KEY, user_id INTEGER, make TEXT, model TEXT, year TEXT, plate TEXT, vin TEXT, image_url TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS bookings (id SERIAL PRIMARY KEY, user_id INTEGER, reference TEXT, make TEXT, model TEXT, year TEXT, plate TEXT, vin TEXT, work_items TEXT, work_summary TEXT, notes TEXT, appt_date TEXT, appt_time TEXT, dropoff TEXT, estimated_min INTEGER DEFAULT 0, customer_name TEXT, customer_phone TEXT, customer_email TEXT, status TEXT DEFAULT 'pending', bill_amount INTEGER, bill_paid INTEGER DEFAULT 0, bill_date TEXT, image_url TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
